constraint.cypher:
MATCH (m:Module) WITH collect(m) AS mods
    WHERE size(mods) > 0 AND NOT EXISTS {
      MATCH (a:Artifact)-[:CONTAINS]->(:Type)-[:DECLARES]->(:Method)-[:INVOKES]->(i:Method)<-[:DECLARES]-(:Type {fqn: 'org.springframework.modulith.core.ApplicationModules'})
      WHERE a.fileName ENDS WITH 'test-classes' AND coalesce(i.name, last(split(split(i.signature, '(')[0], ' '))) = 'verify'
    }
    RETURN mods[0] AS Element, mods[0].fqn AS Fqn, 'ApplicationModules.verify() is not called by any test' AS Detail
